CREATE TABLE public.saved_jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, job_id uuid NOT NULL REFERENCES public.jobs(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,job_id));
GRANT SELECT,INSERT,DELETE ON public.saved_jobs TO authenticated; GRANT ALL ON public.saved_jobs TO service_role;
ALTER TABLE public.saved_jobs ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own saved jobs" ON public.saved_jobs FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.job_alerts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, name text NOT NULL, filters jsonb NOT NULL DEFAULT '{}', enabled boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,name));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.job_alerts TO authenticated; GRANT ALL ON public.job_alerts TO service_role;
ALTER TABLE public.job_alerts ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own job searches" ON public.job_alerts FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
ALTER TABLE public.job_sources ADD COLUMN locked_until timestamptz, ADD COLUMN lock_token uuid, ADD COLUMN retry_after timestamptz, ADD COLUMN failure_count int NOT NULL DEFAULT 0;
CREATE FUNCTION public.claim_job_source(p_id uuid, p_token uuid, p_force boolean DEFAULT false) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.job_sources SET locked_until=now()+interval '5 minutes',lock_token=p_token WHERE id=p_id AND active AND status='connected' AND (locked_until IS NULL OR locked_until<now()) AND (retry_after IS NULL OR retry_after<=now()) AND (p_force OR last_synced_at IS NULL OR last_synced_at+make_interval(mins=>poll_minutes)<=now()); RETURN FOUND; END $$;
REVOKE ALL ON FUNCTION public.claim_job_source(uuid,uuid,boolean) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.claim_job_source(uuid,uuid,boolean) TO service_role;
CREATE FUNCTION public.preserve_job_publication() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.original_posted_at=OLD.original_posted_at; NEW.expires_at=LEAST(NEW.expires_at,OLD.original_posted_at+interval '24 hours'); RETURN NEW; END $$;
CREATE TRIGGER preserve_job_publication BEFORE UPDATE ON public.jobs FOR EACH ROW EXECUTE FUNCTION public.preserve_job_publication();
CREATE TABLE public.job_classifications (job_id uuid PRIMARY KEY REFERENCES public.jobs(id) ON DELETE CASCADE, input_hash text NOT NULL, result jsonb, status text NOT NULL DEFAULT 'pending', error text, updated_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.job_classifications TO service_role; ALTER TABLE public.job_classifications ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.jobs_ai_state (id text PRIMARY KEY, paused boolean NOT NULL DEFAULT false, reason text, updated_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.jobs_ai_state TO service_role; ALTER TABLE public.jobs_ai_state ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.web_vital_samples (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), metric text NOT NULL CHECK(metric IN ('LCP','INP','CLS')), value double precision NOT NULL CHECK(value>=0), rating text NOT NULL CHECK(rating IN ('good','needs-improvement','poor')), path text NOT NULL, device text NOT NULL CHECK(device IN ('mobile','desktop')), created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.web_vital_samples TO service_role; ALTER TABLE public.web_vital_samples ENABLE ROW LEVEL SECURITY; CREATE INDEX web_vital_samples_created_idx ON public.web_vital_samples(created_at);